import assert from 'node:assert/strict'
import test from 'node:test'

import { pruneGeneratedPagesJson } from '../vite-plugins/prune-generated-pages.ts'

test('生产页面清单移除模板页和已停用分包', () => {
  const source = `{
    "pages": [
      // GENERATED BY UNI-PAGES, PLATFORM: H5 || MP-WEIXIN
      { "path": "pages/index/index" },
      // #ifdef MP-WEIXIN
      { "path": "pages/about/about" },
      // #endif
      { "path": "pages/workspace/index" }
    ],
    "subPackages": [
      { "root": "pages-demo", "pages": [{ "path": "chart/index" }] },
      { "root": "pages-housing", "pages": [{ "path": "detail/index" }] }
    ]
  }`

  const result = JSON.parse(pruneGeneratedPagesJson(source, {
    excludedPagePaths: ['pages/about/about', 'pages/workspace/index'],
    excludedSubpackageRoots: ['pages-demo'],
  }))

  assert.deepEqual(result.pages, [{ path: 'pages/index/index' }])
  assert.deepEqual(result.subPackages, [{ root: 'pages-housing', pages: [{ path: 'detail/index' }] }])
})
